public String computeFreightCarrierPricing(
    List<FreightCarrierPricing> freightCarrierPricingList, Long saleOrderId)
    throws AxelorException {
  SaleOrder saleOrder = saleOrderRepository.find(saleOrderId);
  if (saleOrder != null) {
    this.checkSelectedFreightPricingMode(freightCarrierPricingList);
    FreightCarrierPricing freightCarrierPricing = freightCarrierPricingList.get(0);
    saleOrder.setFreightCarrierMode(
        freightCarrierModeRepository.find(freightCarrierPricing.getFreightCarrierMode().getId()));
    saleOrder.setCarrierPartner(
        partnerRepository.find(freightCarrierPricing.getCarrierPartner().getId()));
    saleOrder.setShippingCost(freightCarrierPricing.getPricingAmount());

    if (saleOrder.getEstimatedShippingDate() != null) {
      saleOrder.setEstimatedDeliveryDate(
          saleOrder
              .getEstimatedShippingDate()
              .plusDays(freightCarrierPricing.getDelay().longValue()));
    }

    String message =
        saleOrderShipmentService.createShipmentCostLine(saleOrder, saleOrder.getShipmentMode());
    saleOrderRepository.save(saleOrder);
    return message;
  }
  return null;
}

public Set<FreightCarrierPricing> getFreightCarrierPricingSet(
    Long shipmentModeId, Long saleOrderId) {
  Set<FreightCarrierPricing> freightCarrierPricings = new HashSet<>();
  SaleOrder saleOrder = saleOrderRepository.find(saleOrderId);

  List<FreightCarrierMode> freightCarrierModeList =
      freightCarrierModeRepository
          .all()
          .filter("self.shipmentMode.id = :id")
          .bind("id", shipmentModeId)
          .fetch();

  if (!freightCarrierModeList.isEmpty() && saleOrder != null) {
    freightCarrierModeList.forEach(
        fc -> {
          freightCarrierPricings.add(this.createFreightCarrierPricing(fc, saleOrder));
        });
  }

  return freightCarrierPricings;
}

@Override
public FreightCarrierPricing createFreightCarrierPricing(
    FreightCarrierMode freightCarrierMode, SaleOrder saleOrder) {

  if (freightCarrierMode == null) {
    return null;
  }

  FreightCarrierPricing freightCarrierPricing = new FreightCarrierPricing();
  freightCarrierPricing.setFreightCarrierMode(freightCarrierMode);
  freightCarrierPricing.setCarrierPartner(freightCarrierMode.getCarrierPartner());
  freightCarrierPricing.setPricing(freightCarrierMode.getFreightCarrierPricing());
  freightCarrierPricing.setDelayPricing(freightCarrierMode.getFreightCarrierDelay());
  freightCarrierPricing.setSaleOrder(saleOrder);
  return freightCarrierPricing;

public void updateEstimatedDeliveryDateWithPricingDelay(SaleOrder saleOrder)
    throws AxelorException {
  FreightCarrierPricing freightCarrierPricing =
      this.createFreightCarrierPricing(saleOrder.getFreightCarrierMode(), saleOrder);

  if (freightCarrierPricing == null) {
    return;
  }

  Pricing delay =
      Optional.of(freightCarrierPricing).map(FreightCarrierPricing::getDelayPricing).orElse(null);

  String errors =
      freightCarrierApplyPricingService.computeFreightCarrierPricing(
          delay, freightCarrierPricing);

  if (errors.length() > 0) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_CONFIGURATION_ERROR,
        I18n.get(SupplychainExceptionMessage.FREIGHT_CARRIER_MODE_PRICING_ERROR),
        errors);
  }

  saleOrder.setEstimatedDeliveryDate(
      saleOrder
          .getEstimatedShippingDate()
          .plusDays(freightCarrierPricing.getDelay().longValue()));

protected void planStockMove(StockMove stockMove, boolean splitByTrackingNumber)
    throws AxelorException {
  if (stockMove.getStatusSelect() == null
      || stockMove.getStatusSelect() != StockMoveRepository.STATUS_DRAFT) {
    throw new AxelorException(
        stockMove,
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(StockExceptionMessage.STOCK_MOVE_PLAN_WRONG_STATUS));
  }

  LOG.debug("Stock move planification : {} ", stockMove.getStockMoveSeq());

  // This call will split move line by tracking number
  // But only works if the line has not been already splited
  if (splitByTrackingNumber) {
    stockMoveLineService.splitStockMoveLineByTrackingNumber(stockMove);
  }

  stockMove = JpaModelHelper.ensureManaged(stockMove);
  String draftSeq;

  // Set the sequence.
  if (Beans.get(SequenceService.class)
      .isEmptyOrDraftSequenceNumber(stockMove.getStockMoveSeq())) {
    draftSeq = stockMove.getStockMoveSeq();
    stockMove.setStockMoveSeq(
        stockMoveToolService.getSequenceStockMove(
            stockMove.getTypeSelect(), stockMove.getCompany(), stockMove));
  } else {
    draftSeq = null;
  }

  if (Strings.isNullOrEmpty(stockMove.getName())
      || draftSeq != null && stockMove.getName().startsWith(draftSeq)) {
    stockMove.setName(stockMoveToolService.computeName(stockMove));
  }

  int initialStatus = stockMove.getStatusSelect();

  setPlannedStatus(stockMove);

  updateLocations(stockMove, initialStatus);
  stockMove = JpaModelHelper.ensureManaged(stockMove);
  stockMove.setCancelReason(null);
  stockMove.setRealDate(null);

  stockMove.setExTaxTotal(stockMoveToolService.compute(stockMove));

  stockMoveRepo.save(stockMove);

protected String realizeStockMove(StockMove stockMove, boolean checkOngoingInventoryFlag)
    throws AxelorException {
  if (stockMove.getStatusSelect() == null
      || stockMove.getStatusSelect() != StockMoveRepository.STATUS_PLANNED) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(StockExceptionMessage.STOCK_MOVE_REALIZATION_WRONG_STATUS));
  }

  LOG.debug("Stock realization : {} ", stockMove.getStockMoveSeq());

  if (stockMove.getTypeSelect() == StockMoveRepository.TYPE_INCOMING
      && !stockMove.getIsReversion()
      && appStockService.getAppStock().getIsRequiredShipmentSupplierDetails()
      && (stockMove.getSupplierShipmentDate() == null
          || Strings.isNullOrEmpty(stockMove.getSupplierShipmentRef()))) {
    throw new AxelorException(
        stockMove,
        TraceBackRepository.CATEGORY_MISSING_FIELD,
        I18n.get(StockExceptionMessage.STOCK_MOVE_MISSING_SUPPLIER_SHIPMENT_DETAILS));
  }

  if (checkOngoingInventoryFlag) {
    checkOngoingInventory(stockMove);
  }

  int initialStatus = stockMove.getStatusSelect();

  String newStockSeq = null;
  stockMoveLineService.checkTrackingNumber(stockMove);
  stockMoveLineService.checkConformitySelection(stockMove);
  fillRealizeWapPriceForStockMove(stockMove);

  stockMoveLineService.checkExpirationDates(stockMove);

  BigDecimal exTaxTotal = stockMoveToolService.compute(stockMove);
  stockMove = JpaModelHelper.ensureManaged(stockMove);
  setRealizedStatus(stockMove);
  stockMove.setRealDate(appBaseService.getTodayDate(stockMove.getCompany()));
  stockMove.setExTaxTotal(exTaxTotal);

  stockMove = stockMoveRepo.save(stockMove);

  stockMoveLineService.updateLocations(
      initialStatus,
      StockMoveRepository.STATUS_CANCELED,
      getPlannedStockMoveLineIds(stockMove, true),
      stockMove.getEstimatedDate(),
      false,
      false,
      true);

  stockMoveLineService.updateLocations(
      StockMoveRepository.STATUS_DRAFT,
      StockMoveRepository.STATUS_REALIZED,
      getStockMoveLineIds(stockMove),
      stockMove.getEstimatedDate(),
      true,
      true,
      true);

  stockMove = JpaModelHelper.ensureManaged(stockMove);
  clearPlannedStockMoveLine(stockMove, true);
  storeCustomsCodesForStockMove(stockMove);

@Override
public List<String> checkBlocking(SaleOrder saleOrder) {
  List<String> alertList = new ArrayList<>();
  if (saleOrderBlockingSupplychainService.hasOnGoingBlocking(saleOrder)
      && appSupplychainService.getAppSupplychain().getCustomerStockMoveGenerationAuto()) {
    alertList.add(I18n.get(SupplychainExceptionMessage.SALE_ORDER_LINES_CANNOT_DELIVER));
  }
  return alertList;
